// City mode of the viewer (v0.8.1, spec 6): roam the endless world. Chunks around the view are generated by a worker
// pool (CityQueue decides what runs next) and drawn into two render textures each (ground, objects); chunks far
// outside the view are unloaded. Hover shows a cell's world info, a click selects its block (outline on the overlay
// canvas, why in #cityPanel), double-click / Enter hands the block to onEnterBlock (main.ts, block view).
import type Phaser from 'phaser';
import { VERSION } from '../gen/generate';
import { SHEETS, TILE } from '../gen/types';
import { ZONE_NAME, blockById } from '../world/blocks';
import { chunkRect, worldInfo, type Chunk, type CityBlock, type WorldInfo } from '../world/chunk';
import { CHUNK, CHUNK_KEEP, CHUNK_PREFETCH, CITY_ZOOM } from '../world/config';
import { blocksIn } from '../world/region';
import { CityQueue } from './cityqueue';
import { drawGround, drawObjects, loadTextures } from './draw';
import { WorkerPool, poolSize, type WorkerLike } from './pool';

export interface CityUrl { seed: string; x: number; y: number; z: number }   // x, y = world cell at the view centre

const $ = <T extends HTMLElement>(id: string) => document.getElementById(id) as T;
const esc = (s: unknown) => String(s ?? '').replace(/[&<>"]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]!));
const key = (cx: number, cy: number) => `${cx},${cy}`;
const PX = CHUNK * TILE;   // chunk edge in px

export function toast(msg: string) {
  const t = $('toast'); t.textContent = msg; t.style.display = 'block';
  clearTimeout((toast as unknown as { h: number }).h);
  (toast as unknown as { h: number }).h = window.setTimeout(() => { t.style.display = 'none'; }, 2500);
}

export function download(blob: Blob, name: string) {
  const a = document.createElement('a');
  a.href = URL.createObjectURL(blob); a.download = name;
  document.body.appendChild(a); a.click(); a.remove();
  setTimeout(() => URL.revokeObjectURL(a.href), 2000);
}

/** null when city != 1; bad or missing values fall back to a random seed, the origin, CITY_ZOOM.default */
export function parseCityUrl(q: URLSearchParams, randomSeed: () => string): CityUrl | null {
  if (q.get('city') !== '1') return null;
  const num = (k: string) => { const v = q.get(k); const n = v === null || v.trim() === '' ? NaN : Number(v); return Number.isFinite(n) ? n : undefined; };
  const seed = q.get('seed')?.trim() || randomSeed();
  const z = num('z');
  return {
    seed, x: Math.round(num('x') ?? 0), y: Math.round(num('y') ?? 0),
    z: z !== undefined && z > 0 ? Math.min(CITY_ZOOM.max, Math.max(CITY_ZOOM.min, z)) : CITY_ZOOM.default,
  };
}

/** chunks meeting the view (world cells, half-open) grown by `ring` chunks, nearest (chunk centre to view centre) first */
export function wantedChunks(view: { x0: number; y0: number; x1: number; y1: number }, ring: number): [number, number][] {
  const cx0 = Math.floor(view.x0 / CHUNK) - ring, cy0 = Math.floor(view.y0 / CHUNK) - ring;
  const cx1 = Math.floor((Math.max(view.x1, view.x0 + 1) - 1) / CHUNK) + ring, cy1 = Math.floor((Math.max(view.y1, view.y0 + 1) - 1) / CHUNK) + ring;
  const mx = (view.x0 + view.x1) / 2, my = (view.y0 + view.y1) / 2;
  const out: [number, number, number][] = [];
  for (let cy = cy0; cy <= cy1; cy++) for (let cx = cx0; cx <= cx1; cx++)
    out.push([cx, cy, ((cx + 0.5) * CHUNK - mx) ** 2 + ((cy + 0.5) * CHUNK - my) ** 2]);
  return out.sort((a, b) => a[2] - b[2]).map(([cx, cy]) => [cx, cy]);
}

/** a chunk that came back from the pool: its textures (null while they load) and block ids */
interface Drawn { cx: number; cy: number; ground: Phaser.GameObjects.RenderTexture | null; objects: Phaser.GameObjects.RenderTexture | null; blocks: string[] }

export class CityMode {
  private layer: Phaser.GameObjects.Layer;
  private pool?: WorkerPool;
  private queue: CityQueue;
  private seed = '';
  private active = false;
  private hidden = false;
  private memo = new Map<string, string[]>();      // chunk key -> blocksIn (CityQueue asks every frame)
  private drawn = new Map<string, Drawn>();        // chunks back from the pool (drawn, or loading their textures)
  private failed = new Set<string>();              // chunks whose assembly failed in this epoch (not retried)
  private hoverCell = '';
  private hoverInfo?: WorldInfo;
  private hoverText = '';
  private status = '';
  private selected?: string;
  private t0 = 0;
  private filled = false;
  private lastView = '';
  private dirty = true;

  constructor(private scene: Phaser.Scene, private overlay: HTMLCanvasElement, private onEnterBlock: (seed: string, blockId: string) => void) {
    this.layer = scene.add.layer().setVisible(false);
    this.queue = new CityQueue((cx, cy) => {
      const k = key(cx, cy);
      let ids = this.memo.get(k);
      if (!ids) this.memo.set(k, ids = blocksIn(this.seed, chunkRect(cx, cy)));
      return ids;
    });
    $('cityEnter').onclick = () => this.enterSelected();
  }

  /** start (or restart with a new seed / position) the city view */
  enter(u: CityUrl): void {
    this.clear();
    this.seed = u.seed;
    this.active = true; this.hidden = false;
    this.pool ??= new WorkerPool(() => new Worker(new URL('./city.worker.ts', import.meta.url), { type: 'module' }) as unknown as WorkerLike,
      poolSize(navigator.hardwareConcurrency));
    const cam = this.scene.cameras.main;
    cam.setZoom(u.z);
    cam.centerOn(u.x * TILE + TILE / 2, u.y * TILE + TILE / 2);
    this.layer.setVisible(true);
    this.t0 = performance.now(); this.filled = false;
    const w = window as unknown as { __cityT0: number; __cityIdle: boolean };
    w.__cityT0 = this.t0; w.__cityIdle = false;
    this.status = `世界 ${u.seed} · 生成中…`;
    this.syncUrl();
    this.showInfo();
  }

  /** leave city mode: stop the workers and drop every chunk */
  exit(): void {
    this.clear();
    this.active = false;
    this.pool?.terminate(); this.pool = undefined;
    this.layer.setVisible(false);
  }

  /** the block view covers the city: keep the chunks, stop requesting */
  hide(): void {
    this.hidden = true;
    this.layer.setVisible(false);
    $('cityPanel').style.display = 'none';
    this.overlay.getContext('2d')!.clearRect(0, 0, this.overlay.width, this.overlay.height);
  }

  show(): void {
    this.hidden = false;
    this.layer.setVisible(true);
    this.showPanel();
    this.dirty = true;
  }

  /** every chunk meeting the view (ring 0) drawn (or failed) */
  get idle(): boolean {
    if (!this.active) return false;
    return wantedChunks(this.view(), 0).every(([cx, cy]) => {
      const k = key(cx, cy), d = this.drawn.get(k);
      return (d && d.ground) || this.failed.has(k);
    });
  }

  update(): void {
    if (!this.active || this.hidden) return;
    const v = this.view();
    // unload chunks beyond the keep ring (and forget their block lists)
    const keep = new Set(wantedChunks(v, CHUNK_KEEP).map(([cx, cy]) => key(cx, cy)));
    for (const [k, d] of this.drawn) if (!keep.has(k)) { d.ground?.destroy(); d.objects?.destroy(); this.drawn.delete(k); }
    for (const k of this.memo.keys()) if (!keep.has(k)) this.memo.delete(k);
    for (const k of this.failed) if (!keep.has(k)) this.failed.delete(k);
    this.queue.want(wantedChunks(v, CHUNK_PREFETCH).filter(([cx, cy]) => !this.drawn.has(key(cx, cy)) && !this.failed.has(key(cx, cy))));
    while (this.pool && this.pool.free > 0) {
      const j = this.queue.next();
      if (!j) break;
      if (j.kind === 'block') this.runBlock(j.epoch, j.id);
      else this.runChunk(j.epoch, j.cx, j.cy, j.blocks, j.missing);
    }
    const idle = this.idle;
    (window as unknown as { __cityIdle: boolean }).__cityIdle = idle;
    if (idle && !this.filled) {
      this.filled = true;
      this.status = `世界 ${this.seed} · 一屏画满 ${((performance.now() - this.t0) / 1000).toFixed(1)} 秒`;
      this.showInfo();
    }
    this.drawOverlay();
  }

  /** hover: world px of the pointer; worldInfo only when the cell changes */
  pointerMove(wx: number, wy: number): void {
    if (!this.active || this.hidden) return;
    const info = this.infoAt(wx, wy);
    const [x, y] = this.cellOf(wx, wy);
    this.hoverText = `(${x}, ${y}) · ${ZONE_NAME[info.zone]} · 层 ${info.level} · ${info.blockId ? `街区 ${info.blockId}` : `马路（归街区 ${info.owner}）`}`;
    this.showInfo();
  }

  /** select the block under the pointer (a road cell selects its owner); the selected block again unselects */
  click(wx: number, wy: number): void {
    if (!this.active || this.hidden) return;
    const info = this.infoAt(wx, wy);
    const id = info.blockId ?? info.owner;
    this.selected = this.selected === id ? undefined : id;
    if (this.selected) {
      const [x, y] = this.cellOf(wx, wy);
      $('cityWhy').innerHTML = `<div class="mini">(${x}, ${y})</div>` + info.why.map(w => `<div>${esc(w)}</div>`).join('');
      $('cityBlock').textContent = this.selected;
    }
    this.showPanel();
    this.dirty = true;
  }

  get selection(): string | undefined { return this.selected; }

  enterSelected(): void {
    if (this.active && !this.hidden && this.selected) this.onEnterBlock(this.seed, this.selected);
  }

  clearSelection(): boolean {
    if (!this.selected) return false;
    this.selected = undefined;
    this.showPanel();
    this.dirty = true;
    return true;
  }

  zoomBy(f: number): void {
    const cam = this.scene.cameras.main;
    cam.setZoom(Math.min(CITY_ZOOM.max, Math.max(CITY_ZOOM.min, cam.zoom * f)));
    this.syncUrl();
  }

  /** after a drag or a zoom: x, y, z of the view into the URL */
  syncUrl(): void {
    if (!this.active) return;
    const c = this.centre(), z = +this.scene.cameras.main.zoom.toFixed(4);
    history.replaceState(null, '', `?${new URLSearchParams({ city: '1', seed: this.seed, x: String(c[0]), y: String(c[1]), z: String(z) })}`);
  }

  /** the current frame as PNG + JSON (seed, position, zoom, chunks and blocks in view) */
  exportShot(): void {
    if (!this.active || this.hidden) return;
    const [x, y] = this.centre(), z = +this.scene.cameras.main.zoom.toFixed(4);
    const base = `citygen_v${VERSION}_world${this.seed.replace(/[^\w.-]/g, '_')}_x${x}_y${y}_z${z}`;
    const chunks = wantedChunks(this.view(), 0).filter(([cx, cy]) => this.drawn.get(key(cx, cy))?.ground)
      .sort((a, b) => a[1] - b[1] || a[0] - b[0]);
    const blocks = [...new Set(chunks.flatMap(([cx, cy]) => this.drawn.get(key(cx, cy))!.blocks))].sort();
    const json = { version: VERSION, seed: this.seed, x, y, z, chunks, blocks };
    (window as unknown as { __exportCount: number }).__exportCount = 2;
    this.scene.game.renderer.snapshot(img => {
      const im = img as HTMLImageElement;
      const c = document.createElement('canvas');
      c.width = im.width; c.height = im.height;
      c.getContext('2d')!.drawImage(im, 0, 0);
      c.toBlob(b => {
        download(b!, `${base}.png`);
        download(new Blob([JSON.stringify(json, null, 1)], { type: 'application/json' }), `${base}.json`);
      }, 'image/png');
    });
  }

  // ------------------------------------------------------------------------------------------------

  private clear(): void {
    this.queue.reset();
    for (const d of this.drawn.values()) { d.ground?.destroy(); d.objects?.destroy(); }
    this.drawn.clear(); this.memo.clear(); this.failed.clear();
    this.selected = undefined; this.hoverCell = ''; this.hoverInfo = undefined; this.hoverText = '';
    this.lastView = ''; this.dirty = true;
    $('cityPanel').style.display = 'none';
  }

  private runBlock(epoch: number, id: string): void {
    this.pool!.run<{ block: CityBlock }>({ kind: 'block', seed: this.seed, blockId: id }).then(
      r => this.queue.blockDone(epoch, id, r.block),
      err => {
        if (epoch !== this.queue.epoch) return;
        this.queue.blockDone(epoch, id, null);
        toast(`街区 ${id} 生成失败：${err instanceof Error ? err.message : err}`);
      });
  }

  private runChunk(epoch: number, cx: number, cy: number, blocks: CityBlock[], missing: string[]): void {
    this.pool!.run<{ chunk: Chunk }>({ kind: 'chunk', seed: this.seed, cx, cy, blocks, missing }).then(
      r => { if (this.queue.chunkDone(epoch, cx, cy)) this.drawChunk(r.chunk); },
      err => {
        // always tell the queue, or it never goes idle; a failed chunk is not asked for again in this epoch
        const wanted = this.queue.chunkDone(epoch, cx, cy);
        if (epoch !== this.queue.epoch) return;
        if (wanted) this.failed.add(key(cx, cy));
        toast(`区块 (${cx}, ${cy}) 组装失败：${err instanceof Error ? err.message : err}`);
      });
  }

  /** ground at the chunk's place (depth -1e6), objects in a texture as big as their sprites' bounding box (depth cy:
   *  a lower chunk row covers the one above it) */
  private drawChunk(c: Chunk): void {
    const k = key(c.cx, c.cy);
    const d: Drawn = { cx: c.cx, cy: c.cy, ground: null, objects: null, blocks: c.blocks };
    this.drawn.set(k, d);
    loadTextures(this.scene, SHEETS, c.objects, () => {
      if (this.drawn.get(k) !== d) return;   // unloaded or reset while the textures loaded
      const sc = this.scene;
      const g = sc.add.renderTexture(c.cx * PX, c.cy * PX, PX, PX).setOrigin(0, 0).setDepth(-1e6);
      g.beginDraw();
      drawGround(sc, g, SHEETS, c.ground, 0, 0);
      g.endDraw();
      this.layer.add(g);
      d.ground = g;
      if (c.objects.length) {
        let x0 = Infinity, y0 = Infinity, x1 = -Infinity, y1 = -Infinity;
        for (const o of c.objects) { x0 = Math.min(x0, o.x); y0 = Math.min(y0, o.y); x1 = Math.max(x1, o.x + o.w); y1 = Math.max(y1, o.y + o.h); }
        x0 = Math.floor(x0); y0 = Math.floor(y0);
        const o = sc.add.renderTexture(x0, y0, Math.ceil(x1 - x0), Math.ceil(y1 - y0)).setOrigin(0, 0).setDepth(c.cy);
        o.beginDraw();
        drawObjects(sc, o, c.objects, false, -x0, -y0);
        o.endDraw();
        this.layer.add(o);
        d.objects = o;
      }
    });
  }

  /** world px -> overlay px, matching the main camera (zoom about the viewport centre) */
  private screen() {
    const cam = this.scene.cameras.main, z = cam.zoom;
    return { s: z, ox: cam.scrollX + cam.width / 2 - cam.width / (2 * z), oy: cam.scrollY + cam.height / 2 - cam.height / (2 * z) };
  }

  /** the visible world cells (half-open) */
  private view() {
    const cam = this.scene.cameras.main, v = this.screen();
    const x0 = v.ox, y0 = v.oy, x1 = x0 + cam.width / v.s, y1 = y0 + cam.height / v.s;
    return { x0: Math.floor(x0 / TILE), y0: Math.floor(y0 / TILE), x1: Math.ceil(x1 / TILE), y1: Math.ceil(y1 / TILE) };
  }

  /** world cell at the view centre */
  private centre(): [number, number] {
    const cam = this.scene.cameras.main;
    return [Math.floor((cam.scrollX + cam.width / 2) / TILE), Math.floor((cam.scrollY + cam.height / 2) / TILE)];
  }

  private cellOf(wx: number, wy: number): [number, number] { return [Math.floor(wx / TILE), Math.floor(wy / TILE)]; }

  private infoAt(wx: number, wy: number): WorldInfo {
    const [x, y] = this.cellOf(wx, wy), k = key(x, y);
    if (k !== this.hoverCell || !this.hoverInfo) { this.hoverCell = k; this.hoverInfo = worldInfo(this.seed, x, y); }
    return this.hoverInfo;
  }

  private showInfo(): void { $('info').textContent = [this.hoverText, this.status].filter(Boolean).join(' · '); }

  private showPanel(): void { $('cityPanel').style.display = this.selected && !this.hidden ? 'block' : 'none'; }

  /** the selected block's footprint on the overlay canvas (redrawn when the camera moves) */
  private drawOverlay(): void {
    const v = this.screen(), cam = this.scene.cameras.main;
    const k = `${v.s}|${v.ox}|${v.oy}|${cam.width}|${this.overlay.width}|${this.overlay.height}`;
    if (k === this.lastView && !this.dirty) return;
    this.lastView = k; this.dirty = false;
    const ctx = this.overlay.getContext('2d')!;
    ctx.clearRect(0, 0, this.overlay.width, this.overlay.height);
    if (!this.selected) return;
    ctx.lineWidth = 2; ctx.strokeStyle = '#ffd54f';
    for (const f of blockById(this.seed, this.selected).foot) {
      const x = (f.x0 * TILE - v.ox) * v.s, y = (f.y0 * TILE - v.oy) * v.s;
      ctx.strokeRect(x, y, (f.x1 - f.x0) * TILE * v.s, (f.y1 - f.y0) * TILE * v.s);
    }
  }
}
